\label{der-prop}
    We define $G^{\chi}=i^{\chi}s_0^{2\chi}\hat{{\mathcal G}}^{\chi}$, where $\hat{\mathcal{G}^\chi}$ is the regular function on ${\sf S}$ obtained after applying the dictionary~\ref{tab:dictionary}.

    We can relate the vector fields $\sf R_i$ with the derivations on $\mathcal M$. 
    \begin{align}
       5i^{\chi}G_{z\bar z}^{-1} D_z \mathcal G^\chi = (s_0^{-2\chi}{\sf R}_0G^\chi)\circ\sigma\\
        5^{-6}G_{z\bar z}^{-2}\frac{\partial}{\partial S^{zz}}= (-s_0^{4}{\sf R}_4(-))\circ\sigma\\
       5^{-7}G_{z\bar z}^{-1} \frac{\partial}{\partial \Delta^z} = (i\ s_0^{2}{\sf R}_7(-))\circ\sigma
    \end{align}

    In particular, these expressions lift to expressions involving the regular functions on the left of Table~\ref{tab:dictionary} and the derivatives defined in Lemma~\ref{lem:dict-jac}.

We compute directly:

\begin{equation}\label{eq:derprop-1}
\begin{aligned}
({\sf R}_0G^{\chi})\circ\sigma&=i^{\chi}\left(\big({\sf R}_0(s_0^{2\chi})\big)\circ\sigma\cdot\mathcal G^{\chi}+(s_0\circ\sigma)^{2\chi}\cdot\big({\sf R}_0(i^{-\chi}s_0^{-2\chi}G^{\chi})\big)\circ\sigma\right)\\
&=i^{\chi}\left(\big(2\chi s_0^{2\chi-1}{\sf R}_0(s_0)\big)\circ\sigma\cdot\mathcal G^{\chi}+(s_0\circ\sigma)^{2\chi}\cdot\big({\sf R}_0(i^{-\chi}s_0^{-2\chi}G^{\chi})\big)\circ\sigma\right)
\end{aligned}
\end{equation}

        By the discussion above, Lemma~\ref{lem:Gzz and R0} and the explicit formula of ${\sf R}_0$ in Equation~\eqref{eq:R0}, we have

\begin{equation}\label{eq:derprop-2}
({\sf R}_0G^{\chi})\circ\sigma=i^{\chi}\left(\chi\left(s_0^{2\chi-2}\,\frac{3750s_0^{10}+s_0^2s_3-625s_4^{10}}{s_5}\right)\circ\sigma\cdot\mathcal G^{\chi}+(s_0\circ\sigma)^{2\chi}5G_{z\bar z}^{-1}\cdot\partial_z\mathcal G^{\chi}\right)
\end{equation}

        Using that $e^{-K}$, $G_{z\bar z}$ and $K_z$ can be expressed in terms of the variables $s_i$ as in~\ref{tab:dictionary}, we write:

\begin{equation}\label{eq:derprop-3}
\begin{aligned}
(s_0^{-2\chi}{\sf R}_0(G^{\chi}))\circ\sigma
&=i^{\chi}\left(-5\chi K_zG_{z\bar z}^{-1}\mathcal G^{\chi}+5G_{z\bar z}^{-1}\partial_z\mathcal G^{\chi}\right)\\
&=5i^{\chi}G_{z\bar z}^{-1}\cdot (-\chi K_z \mathcal G^{\chi}+\partial_z\mathcal G^{\chi})=5i^{\chi}G_{z\bar z}^{-1}D_z\mathcal G^{\chi}
\end{aligned}
\end{equation}


        For the second equality, we use that $S^{zz}$ can be written in terms of the $s_i$ as 
\begin{equation}\label{eq:derprop-Szz}
